const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g 'entry.js' -g 'csv.js' -g 'stock.js' -g 'sku.js' -g 'wire.js' -g 'package.json' -g '*test*' -g 'answer.json' -g '!node_modules'",max_output_tokens:4000}),
  tools.exec_command({cmd:"git status --short --branch",max_output_tokens:1500})
]);
for (let i = 0; i < results.length; i++) {
  const r = results[i];
  text({stage: i === 0 ? "file_inventory" : "git_status", status: r.status, result: r.status === "fulfilled" ? r.value : String(r.reason)});
}

const results = await Promise.allSettled([
  tools.exec_command({cmd:"rg --files -g '!node_modules' -g '!answer.json'",max_output_tokens:3000}),
  tools.exec_command({cmd:"for f in src/entry.js src/input/csv.js src/domain/stock.js src/domain/sku.js src/output/wire.js src/output/csv.js package.json; do printf '\\n--- %s ---\\n' \"$f\"; nl -ba \"$f\"; done",max_output_tokens:8000})
]);
for (let i = 0; i < results.length; i++) {
  const r = results[i];
  text({stage: i === 0 ? "workspace_files" : "pipeline_source", status: r.status, result: r.status === "fulfilled" ? r.value : String(r.reason)});
}

